package com.troday.api.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="reports") public class Report { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="reporter_id") private Long reporterId; private String type; @Column(name="reported_user_id") private Long reportedUserId; @Column(name="reported_post_id") private Long reportedPostId; @Column(name="contract_id") private Long contractId; @Column(name="roommate_request_id") private Long roommateRequestId; @Lob private String reason; private String status="PENDING"; @Lob private String resolution; @Column(name="handled_by_id") private Long handledById; private LocalDateTime handledAt; public Long getId(){return id;} public Long getReporterId(){return reporterId;} public void setReporterId(Long v){reporterId=v;} public String getType(){return type;} public void setType(String v){type=v;} public Long getReportedUserId(){return reportedUserId;} public void setReportedUserId(Long v){reportedUserId=v;} public Long getReportedPostId(){return reportedPostId;} public void setReportedPostId(Long v){reportedPostId=v;} public Long getContractId(){return contractId;} public void setContractId(Long v){contractId=v;} public Long getRoommateRequestId(){return roommateRequestId;} public void setRoommateRequestId(Long v){roommateRequestId=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getResolution(){return resolution;} public void setResolution(String v){resolution=v;} public Long getHandledById(){return handledById;} public void setHandledById(Long v){handledById=v;} public LocalDateTime getHandledAt(){return handledAt;} public void setHandledAt(LocalDateTime v){handledAt=v;} }
